{
  "didatica": [
    {
      "campo": "resolucao.antes.texto",
      "depois": "A questão pede que você julgue três afirmações sobre marcas de subjetividade (a presença de quem fala, com seus sentimentos e opiniões) em três textos. Teste cada afirmação só contra o texto citado nela, não contra o que você já sabe do assunto. Texto teórico e texto informativo costumam usar a 3ª pessoa e não mostram opinião pessoal. Poema romântico costuma usar a 1ª pessoa e expressar emoção.",
      "motivo": "Define subjetividade com palavras simples e deixa a ordem de leitura clara."
    },
    {
      "campo": "resolucao.antes.simbolos",
      "depois": [
        ["subjetivo", "que mostra quem fala: seus sentimentos, sua opinião, sua experiência"],
        ["1ª pessoa", "quando o texto fala com 'eu' ou 'nós' (eu deliro, dizei-me)"],
        ["3ª pessoa", "quando o texto fala de algo sem o 'eu' (Há os que entendem...)"],
        ["adjetivação", "uso de muitos adjetivos, as palavras que dão qualidade ao substantivo (belo, profundo)"],
        ["eu lírico", "voz que fala no poema; não é necessariamente o autor, mas expressa emoção em 1ª pessoa"],
        ["conotação", "sentido figurado, que vai além do sentido de dicionário"],
        ["impessoalidade", "linguagem que não mostra quem fala nem sua opinião, com foco nos fatos"],
        ["recurso emotivo", "elemento de linguagem que expressa sentimento de quem fala"],
        ["seleção lexical", "escolha das palavras que o autor usa"]
      ],
      "motivo": "Termos como 1ª pessoa, adjetivação e seleção lexical apareciam sem explicação."
    },
    {
      "campo": "resolucao.pista",
      "depois": "Teste uma afirmação por vez, voltando ao texto citado. Em I e III, procure no texto uma marca que contradiga a afirmação: há 'eu'? Há opinião ou vida pessoal do autor?",
      "motivo": "Deixa a pergunta de teste concreta sem entregar a resposta."
    },
    {
      "campo": "resolucao.passos[0].porque",
      "depois": "O Texto I explica uma teoria em 3ª pessoa, sem 'eu', e usa palavras no sentido comum. A afirmação I diz que a subjetividade está na 'totalidade' dele. Basta o texto ser impessoal para ela ser falsa.",
      "motivo": "Frases mais curtas e raciocínio direto."
    },
    {
      "campo": "resolucao.passos[1].porque",
      "depois": "Há 1ª pessoa ('eu', 'dizei-me'), perguntas, exclamações e palavras fortes como 'horror' e 'borrão'. Pontuação e vocabulário expressam o horror do eu lírico diante do navio negreiro. A afirmação II confere.",
      "motivo": "Liga os trechos à afirmação II."
    },
    {
      "campo": "resolucao.passos[2].porque",
      "depois": "O texto define, dá datas e cita fontes, tudo em 3ª pessoa. Não há opinião do autor nem exemplo da vida dele. A afirmação III é falsa.",
      "motivo": "Clareza e fecha o raciocínio do passo."
    }
  ],
  "didatica_alertas": [],
  "didatica_ok": true
}
